// Helper to write JSON database file
function writeDb(data) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2));
  } catch (err) {
    console.error("Error writing database file:", err);
  }
}

export const DataStore = {
  // Authentication methods
  async signup({ username, phoneOrEmail, password }) {
    const db = readDb();
    const normalizedInput = phoneOrEmail.trim().toLowerCase();

    // Check if user already exists
    const existing = db.users.find(
      u => u.phoneOrEmail.toLowerCase() === normalizedInput || u.username.toLowerCase() === username.trim().toLowerCase()
    );

    if (existing) {
      throw new Error("An account already exists with this Email/Phone or Username. Please Sign In!");
    }

    const salt = await bcrypt.genSalt(10);
    const passwordHash = await bcrypt.hash(password, salt);

    const newUser = {
      _id: `user-${Date.now()}`,
      username: username.trim(),
      phoneOrEmail: normalizedInput,
      passwordHash,
      createdAt: new Date().toISOString()
    };

    db.users.push(newUser);
    writeDb(db);

    const token = jwt.sign({ id: newUser._id, username: newUser.username }, JWT_SECRET, { expiresIn: '7d' });

    return {
      token,
      user: {
        id: newUser._id,
        username: newUser.username,
        phoneOrEmail: newUser.phoneOrEmail
      }
    };
  },

  async login({ phoneOrEmailOrUsername, password }) {
    const db = readDb();
    const query = phoneOrEmailOrUsername.trim().toLowerCase();

    const user = db.users.find(
      u => u.phoneOrEmail.toLowerCase() === query || u.username.toLowerCase() === query
    );

    // Explicit check 1: User does not exist
    if (!user) {
      const err = new Error("ACCOUNT_NOT_FOUND");
      err.customMessage = "No registered account found with these credentials. Please Sign Up first to create your account!";
      throw err;
    }

    // Explicit check 2: Incorrect Password
    const isMatch = await bcrypt.compare(password, user.passwordHash);
    if (!isMatch) {
      const err = new Error("INVALID_PASSWORD");
      err.customMessage = "Login Failed: Incorrect password entered. Please try again.";
      throw err;
    }

    const token = jwt.sign({ id: user._id, username: user.username }, JWT_SECRET, { expiresIn: '7d' });

    return {
      token,
      user: {
        id: user._id,
        username: user.username,
        phoneOrEmail: user.phoneOrEmail
      }
    };
  },

  // Electronics Products methods
  async getProducts({ category, search, city } = {}) {
    const db = readDb();
    let list = db.products || [];

    if (category && category !== 'all') {
      list = list.filter(p => p.category === category);
    }

    if (city && city !== 'All India') {
      list = list.filter(p => p.city === city);
    }

    if (search && search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(
        p => (p.title || '').toLowerCase().includes(q) ||
             (p.brand || '').toLowerCase().includes(q) ||
             (p.workingCondition || '').toLowerCase().includes(q) ||
             (p.problems || '').toLowerCase().includes(q)
      );
    }

    return list;
  },

  async createProduct(productData) {
    const db = readDb();
    const newProd = {
      _id: `prod-${Date.now()}`,
      ...productData,
      createdAt: new Date().toISOString()
    };

    if (!db.products) db.products = [];
    db.products.unshift(newProd);
    writeDb(db);
    return newProd;
  },

  async deleteProduct(productId, userId) {
    const db = readDb();
    if (!db.products) db.products = [];
    const initialLen = db.products.length;
    db.products = db.products.filter(p => !(p._id === productId && p.sellerId === userId));
    writeDb(db);
    return db.products.length < initialLen;
  }
};
